# -*- coding: utf-8 --

import re
import time
from robot.api import logger
import os
from taf.rfrl.cbts.connections.ssh_connections import SSHConnExec
from taf.rfrl.cbts.utilities import generic_utils
from taf.internal.robot_typecasts.typecasts import time_to_seconds

LOG_HEAD = LOG_END = "*" * 8


class FHGWOpe(SSHConnExec):

    def save_fhgw_snapshot(self, local_dir=None, timeout=300, conn_alias='default'):
        """
        Saving fhgw snapshot file by cli command.

        :param str local_dir: the local directory that snapshot file stored, if it is not given, a directory
                              which is constructed with robot log output directory, test name,
                              log type and timestamp will be created.
        :param Union[int,str] timeout: (optional) Timeout for the operation, default is 300s
        :param str conn_alias: ssh connection alias
        :return str: local snapshot file path.
        """
        curr_prompt = self.ssh_conn.get_prompt(alias=conn_alias)
        cmd = 'snapshot save' if 'fhgwcli' in curr_prompt else 'fhgwcli snapshot save'
        save_snapshot_res = self.execute_normal_cmd(base_command=cmd, alias=conn_alias)
        try:
            snapshot_file_name = re.search('Collection started for report:\\s(.+)', save_snapshot_res).group(1)
            logger.info('{} FHGW snapshot file name is {} {}'.format(LOG_HEAD, snapshot_file_name, LOG_END))
        except Exception:
            raise Exception('Does not get FHGW snapshot file')

        self._verify_fhgw_snapshot_saving_status(snapshot_file_name,
                                                 timeout=time_to_seconds(timeout),
                                                 conn_alias=conn_alias)
        local_file_path = self.download_fhgw_snapshot_file_to_local(snapshot_file_name, local_dir, conn_alias)
        return local_file_path

    def _verify_fhgw_snapshot_saving_status(self, file_name, timeout=300, conn_alias='default'):
        cmd = 'fhgwcli snapshot list reports'
        endtime = time.time() + timeout
        while time.time() < endtime:
            status_info = self.execute_normal_cmd(base_command=cmd, alias=conn_alias)
            logger.info('Snapshot status info is {}'.format(status_info))
            status = re.search('{}\\s(.+)'.format(file_name), status_info, re.M)

            if 'SUCCESS' in status.group(1):
                logger.info('{} FHGW snapshot save finished {}'.format(LOG_HEAD, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception('FHGW snapshot saving is not finished in the given 5 minutes!')

    def download_fhgw_snapshot_file_to_local(self, file_name, local_path=None, conn_alias='default'):
        if local_path:
            snapshot_file_local_path = local_path
        else:
            snapshot_file_local_path = generic_utils.generate_log_path_with_log_type(log_type='fhgw_snapshot')

        remote_file_path = '/mnt/symptomreport/{}.tar'.format(file_name)
        local_file_path = snapshot_file_local_path + '/' + file_name + '.tar'

        logger.info('{} Start downloading snapshot file from {} to {} {}'.format(LOG_HEAD, remote_file_path,
                                                                                 local_file_path, LOG_END))
        self.download_file(remote_path=remote_file_path,
                           local_path=local_file_path,
                           alias=conn_alias)

        if not os.path.isfile(local_file_path):
            raise AssertionError('{} does not exist.'.format(local_file_path))

        return local_file_path

    def get_fhgw_release(self, gnb_index=0, vdu_index=0, fhgw_index=0):
        self.ssh_connection_to_fhgw(gnb_index=gnb_index, vdu_index=vdu_index,
                                    fhgw_index=fhgw_index, alias='fhgw-release')
        try:
            cont = self.execute_normal_cmd('cat /etc/fhgw-release')
            fhgw_release = re.search('release=\\S(.+)', cont, re.M).group(1).split('_')[0]
            return fhgw_release
        finally:
            self.disconnect_fhgw_ssh_conn(alias='fhgw-release')

    def get_fhgw_id(self, gnb_index=0, vdu_index=0, fhgw_index=0):
        self.ssh_connection_to_fhgw(gnb_index=gnb_index, vdu_index=vdu_index,
                                    fhgw_index=fhgw_index, alias='fhgw-id')
        try:
            fhgw_id = self.execute_normal_cmd('cat /etc/fhgwID')
            return fhgw_id
        finally:
            self.disconnect_fhgw_ssh_conn(alias='fhgw-id')
